open my $fh, "<", "po" or die "Cannot Open $stderr: $!";
open my $tmp, "a" or die "Cannot Open $tmp: $!";

while (<$fh>) {
    my $line = $tmp-><$fh>;
    for (my $line =~ /pattern/) {
        substr($line, 1);
    }
    print "$line\n";
}
close $fh;
```

